import './index';

const hidden = 1;
type Box = { value: number };
declare const typed: Box;
declare function returning(): { returned: number };

export namespace Cyclic {
  export import Self = Cyclic;
  export const member = hidden;
}

namespace PrivateSpace {
  const privateValue = hidden;
  export const visible = privateValue;
  namespace Inner {
    const nested = visible;
  }
}

class PrivateClass {
  private child!: PrivateClass;
  static create() {
    const functionLocal = new PrivateClass();
    return functionLocal;
  }
  run(parameter: number) {
    const methodLocal = parameter;
    return methodLocal;
  }
}

function factory() {
  const localOnly = PrivateClass.create();
  return localOnly;
}

export {};
